import MaximunDemandScreen from './screens/MaximunDemandScreen'
import UploadWaterScreen from './screens/UploadWaterScreen'
import NavigationBar from './Components/NavigationBar'

function App() {
  return (
    <Router>
       <Routes>

      <main>
      <Route path="/login" element={ 
                        <LoginScreen/>

                } />

      </main>
      <Footer />
      </Routes>
    </Router>
  );
}

export default App;
